export function roomBar(client,esc){
 const s=client.snapshot;if(!client.session)return '';
 const state=client.status==='connected'?s?.slots.every(p=>p?.connected)?'İKİ OYUNCU BAĞLI':'RAKİP BEKLENİYOR':client.status==='replaced'?'BAŞKA SEKMEDE AÇILDI':'YENİDEN BAĞLANIYOR';
 return `<div class="room-status-bar ${client.status!=='connected'?'offline':''}"><span><i class="live-dot"></i> ODA <b>${esc(s?.code||client.session.code||'…')}</b> · ${state}</span><div>${s?`<small>Sen: ${esc(s.slots[s.side]?.name||'')} · P${s.side+1}</small>`:''}<button data-action="room-invite">Davet ↗</button><button data-action="room-leave">Odadan ayrıl</button></div></div>${s&&s.status!=='lobby'&&s.status!=='closed'&&!s.slots.every(p=>p?.connected)?'<div class="room-reconnect" role="status">Bağlantı bekleniyor. Teklif saati ve mücadele durdu; yeniden katılmak için 2 dakika var.</div>':''}`;
}
export function roomLobby(client,esc){
 const s=client.snapshot,connected=client.status==='connected',closed=s?.status==='closed';
 return `<main class="room-lobby"><div class="room-lobby-title"><div class="eyebrow">İKİ EKRAN. TEK MÜCADELE.</div><h1>${closed?'Oda sona erdi.':'Rakibini davet et.<br><em>Sahneyi paylaş.</em>'}</h1><p>${closed?esc(s.notice)+(s.closedWinner!==null?' '+esc(s.slots[s.closedWinner]?.name||'Rakip')+' kazandı.':''):'Her oyuncu kendi cihazından teklif verir ve kendi takımını yönetir.'}</p></div><section class="room-card"><div class="room-code"><span>ODA KODU</span><strong>${esc(s?.code||client.session?.code||'······')}</strong><button class="outline" data-action="room-invite">Davet bağlantısını göster ↗</button></div><div class="room-slots">${[0,1].map(i=>{const p=s?.slots[i];return `<div class="room-slot side-${i}"><span class="room-avatar">0${i+1}</span><div><small>${i===0?'ODA SAHİBİ':'RAKİP'}</small><h2>${p?esc(p.name):'Arkadaşın bekleniyor'}</h2><p>${p?p.connected?p.ready?'✓ Hazır':'Hazır olduğunu bildiriyor…':'Bağlantı bekleniyor…':'Kodu veya bağlantıyı paylaş.'}</p></div>${s?.side===i?'<b>SEN</b>':''}</div>`;}).join('')}</div><p class="room-notice" role="status">${connected?esc(s?.notice||''):client.status==='failed'?'Bağlanılamadı. Oda kodunu kontrol et.':client.status==='replaced'?'Oyuncun başka sekmede açıldı. Bu sekmeden işlem yapılamaz.':'Sunucuya bağlanılıyor…'}</p><div class="room-lobby-actions">${closed?`<button class="primary" data-action="room-local">Yerel oyuna dön</button>`:`<button class="primary" data-action="room-ready" ${!connected||client.pending?'disabled':''}>${s?.slots[s.side]?.ready?'Hazır değilim':'Hazırım ✓'}</button>${s?.side===0?`<button class="outline" data-action="room-launch" ${connected&&!client.pending&&s.slots.every(p=>p?.connected&&p.ready)?'':'disabled'}>Müzayedeyi başlat →</button>`:''}<button class="text-button" data-action="room-local">Yerel oyuna dön</button>`}</div></section><div class="room-rules"><div><b>20 COIN</b><span>İki oyuncuya da eşit bütçe.</span></div><div><b>20 SANİYE</b><span>Her teklif sırası yeniden başlar.</span></div><div><b>GİZLİ KARTLAR</b><span>Sıradaki kahramanı kimse göremez.</span></div></div></main>`;
}
